import pandas as pd
import matplotlib.pyplot as plt
import os

# Load the data generated by your simulation
df_attack = pd.read_csv("data/attack_results.csv")
df_defense = pd.read_csv("data/defense_results.csv")

def plot_scenario(ax, df, title):
    # Calculate the average reputation per round for honest vs malicious agents
    honest_avg = df[df['is_malicious'] == False].groupby('round')['reputation'].mean()
    malicious_avg = df[df['is_malicious'] == True].groupby('round')['reputation'].mean()

    # Plot the lines
    ax.plot(honest_avg.index, honest_avg.values, label="Honest Agents (Avg)", color="#1f77b4", linewidth=2.5)
    ax.plot(malicious_avg.index, malicious_avg.values, label="Colluding Agents (Avg)", color="#d62728", linestyle="--", linewidth=2.5)
    
    ax.set_title(title, fontsize=12, fontweight='bold')
    ax.set_xlabel("Marketplace Round", fontsize=10)
    ax.set_ylabel("Average Reputation Score", fontsize=10)
    ax.legend()
    ax.grid(True, linestyle=':', alpha=0.7)

# Set up a side-by-side plot layout
fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 5))

plot_scenario(ax1, df_attack, "Vulnerable: Sybil Attack Overwhelms System")
plot_scenario(ax2, df_defense, "Fixed: Gateway Monitor Blocks Fake Work")

# Add a main title for the whole graphic
plt.suptitle("Impact of Transcript Verification on AI Agent Reputation Gaming", fontsize=14, fontweight='bold', y=1.05)

plt.tight_layout()

# Save the high-res image for the PDF report
os.makedirs("docs", exist_ok=True)
plt.savefig("docs/reputation_graph.png", dpi=300, bbox_inches='tight')
print("Success! Graph saved to docs/reputation_graph.png")

# Display the graph on your screen right now
plt.show()